#include "scarlett_link64.hpp"
#include <cassert>
int main(int argc,char**argv){assert(argc==2); genesis::GuestMemory64 m;genesis::ScarlettImports64 i;assert(i.install(m));genesis::ScarlettLink64 l(m,[&](const std::string&){std::ifstream f(argv[1],std::ios::binary);return std::vector<uint8_t>((std::istreambuf_iterator<char>(f)),{});});l.entrylessOnly=true; i.bindDynamicLoader([&](const std::string& n){if(!l.link(n)){std::cerr<<l.error<<"\n";return uint64_t(0);}auto& v=l.modules.at(n);assert(i.publishEntrylessModule(n,v.pe.imageBase,v.exports.addresses));return v.pe.imageBase;});auto load=i.registerImport("api-ms-win-core-libraryloader-l1-2-0.dll","LoadLibraryExW");auto proc=i.registerImport("api-ms-win-core-libraryloader-l1-2-0.dll","GetProcAddress");assert(load&&proc);assert(m.map(0x100000,4096,3)==genesis::GuestMemory64::Fault::none);std::array<uint8_t,16> name{'a',0,'.',0,'d',0,'l',0,'l',0};assert(m.write(0x100000,name)==genesis::GuestMemory64::Fault::none);uint64_t h=0,a=0;assert(i.dispatch(load,m,0x100000,h,0,0)&&h);std::array<uint8_t,4> sym{'f','o','o',0};assert(m.write(0x100100,sym)==genesis::GuestMemory64::Fault::none);assert(i.dispatch(proc,m,h,a,0x100100)&&a==l.modules.at("a.dll").exports.addresses.at("foo"));std::cout<<"V86 live entryless DLL lookup passed\n";}
